/**
 * Full migrated content of the old trustbank.uz (generated by scripts/legacy/convert.mjs).
 * SERVER ONLY — import from server components / route files, never from "use client" modules,
 * otherwise several MB of text end up in the browser bundle.
 */
import PAGES from "./pages.json";
import PAGES_UZ from "./pages.uz.json";
import PAGES_EN from "./pages.en.json";
import OFFICES from "./offices.json";
import type { LegacyPage } from "@/types/content";
import type { Language } from "@/types/pageConfig";
import { inSection, type LegacySection } from "./sections";

export const LEGACY_PAGES = PAGES as unknown as Record<string, LegacyPage>;

export interface LegacyOffice {
  name: string;
  slug: string;
  address: string;
  phone: string;
  fax: string;
}

export const LEGACY_OFFICES = OFFICES as LegacyOffice[];

export const getLegacyPage = (key: string): LegacyPage | undefined => LEGACY_PAGES[key];

const BY_LANG: Record<Exclude<Language, "ru">, Record<string, LegacyPage>> = {
  uz: PAGES_UZ as unknown as Record<string, LegacyPage>,
  en: PAGES_EN as unknown as Record<string, LegacyPage>,
};

/**
 * The page in the requested language (Uzbek / English versions scraped from the old site).
 * `fallback` is true when that version does not exist and the Russian one is returned.
 */
export function getLegacyPageIn(key: string, lang: Language): { page: LegacyPage; fallback: boolean } | undefined {
  const ru = LEGACY_PAGES[key];
  if (!ru) return undefined;
  if (lang === "ru") return { page: ru, fallback: false };
  const loc = BY_LANG[lang][key];
  return loc?.blocks.length ? { page: { ...loc, path: ru.path, detail: ru.detail }, fallback: false } : { page: ru, fallback: true };
}

/** Title of a migrated page in the requested language (Russian when there is no translation). */
export const legacyTitleIn = (key: string, lang: Language) => getLegacyPageIn(key, lang)?.page.title ?? key;

const BY_PATH = new Map(
  Object.entries(LEGACY_PAGES)
    .filter(([, p]) => p.path)
    .map(([k, p]) => [p.path!, k] as const)
);

/** Legacy key of the page served at `path` (menu pages and third-level detail pages). */
export const legacyKeyByPath = (path: string): string | undefined => BY_PATH.get(path);

/** Every routed page of a section, including detail pages that are not in its menu. */
export const sectionAllKeys = (s: LegacySection): string[] =>
  Object.entries(LEGACY_PAGES)
    .filter(([k, p]) => inSection(s, k, p))
    .map(([k]) => k);

/** Detail pages under an old-site prefix (e.g. "about/central-office"). */
export const legacyDetailKeys = (prefix: string): string[] =>
  Object.entries(LEGACY_PAGES)
    .filter(([k, p]) => p.detail && p.path && k.startsWith(prefix + "/"))
    .map(([k]) => k);

/** Ancestors of `key` (outermost first) that exist as migrated pages. */
export function legacyAncestors(key: string): string[] {
  const parts = key.split("/");
  const out: string[] = [];
  for (let i = 1; i < parts.length; i++) {
    const k = parts.slice(0, i).join("/");
    if (LEGACY_PAGES[k]?.path) out.push(k);
  }
  return out;
}
